def solve(jobs):
    jobs = list(jobs)
    by_id = {j['id']: j for j in jobs}

    # missing dependency invalidates the whole graph
    for job in jobs:
        for dep in job['deps']:
            if dep not in by_id:
                return {'status': 'invalid', 'finish': [], 'late': []}

    # cycle detection via DFS
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {j['id']: WHITE for j in jobs}

    def has_cycle(root):
        stack = [(root, 0)]
        while stack:
            node, i = stack[-1]
            if i == 0:
                color[node] = GRAY
            deps = by_id[node]['deps']
            if i < len(deps):
                stack[-1] = (node, i + 1)
                dep = deps[i]
                if color[dep] == WHITE:
                    stack.append((dep, 0))
                elif color[dep] == GRAY:
                    return True
            else:
                color[node] = BLACK
                stack.pop()
        return False

    for job in jobs:
        if color[job['id']] == WHITE:
            if has_cycle(job['id']):
                return {'status': 'invalid', 'finish': [], 'late': []}

    pending = {j['id']: j for j in jobs}
    finished = {}

    while pending:
        progress = False
        for name, job in list(pending.items()):
            if ready(job, pending, finished):
                finished[name] = end_time(job, finished)
                del pending[name]
                progress = True
        if not progress:
            return {'status': 'invalid', 'finish': [], 'late': []}

    return report(jobs, finished)
